#include "common.h"

extern int D_00000000;
typedef struct { int w; } SC4_; /* run 131 struct-copy lever: 4-byte word copy type */

#ifdef NON_MATCHING
/* Macro definitions for NM-wrap bodies. Auto-managed by /struct-name-tick.
 * Default build never sees these — wrap bodies aren't compiled.
 * GL_COUNT_2070: element count — read into `count`/`n`/`m` locals and used
 * as a multiplier in indexing. game_libs D+0x2070.
 */
#define GL_COUNT_2070 (*(int*)((char*)&D_00000000 + 0x2070))
#endif

typedef struct { int a, b, c, d; } Quad4;
typedef struct { int a, b, c; } Tri3i;
typedef struct { int a, b; } Pair2;
typedef struct { float x, y, z; } Vec3;

/* game_libs_func_0001C9E4 -- EXACT (run 136). Was gl_func_0001CA10 (648 B, no C):
 * a mid-function split. The real entry's first 11 words (the `k * 344` record
 * index chain + the hoisted `lbu f4`) sat at the end of the game_libs_text2_tail
 * bin (ROM 0xE01ABC); tenshoe.yaml's game_libs_post start moved 0xE01AE8 ->
 * 0xE01ABC (ROM bytes unchanged; assets/game_libs_text2_tail.bin shrinks by
 * 0x2C -- re-run `make setup` in other checkouts). bootup.uso exports neither
 * 0x1CA10 nor 0x1C9E4 (its Sym 1229 is the pad start 0x1C9D4).
 * Per (record k, slot j): unless the record is short (f4 < 3) or busy (f2),
 * clear the slot's 0x340-byte buffer, copy its two s16 streams (stride f4) into
 * the record's ring at offC then at 0; then requeue: q = n / f4 entries, split
 * at the ring end f1C (n10 / n12 are byte counts). The 0x340 callee is a blank
 * import (jal 0). Levers: s assigned before both early tests, e recomputed
 * BEFORE q in the tail, e declared first, one unused 2-word pad (frame 0x48). */
typedef struct { s16 f0; s16 f2; s16 *p4; s16 *p8; s32 offC; s16 n10; s16 n12; } VbElem;
typedef struct {
    u8 pad0[2]; u8 f2; u8 f3; u8 f4; u8 pad5[0xF];
    s32 f14; s32 f18; s32 f1C; s16 *p20; s16 *p24; u8 pad28[0x10];
    VbElem e[2][5]; u8 rest[64];
} VbSub;
typedef struct { u8 pad[0x18]; VbSub sub; } VbRec;
extern int gl_func_00000000();
void game_libs_func_0001C9E4(int n, int j, int k) {
    VbElem *e;
    VbRec *r = &((VbRec *)&D_00000000)[k];
    VbSub *s;
    int pad[2];
    int i, idx, q, rem;
    s = &r->sub;
    if (s->f4 >= 3 && s->f2 == 0) {
        e = &s->e[s->f3][j];
        gl_func_00000000(e->p4, 0x340);
        idx = 0;
        for (i = 0; i < e->n10 / 2; i++) {
            s->p20[e->offC + i] = e->p4[idx];
            s->p24[e->offC + i] = e->p8[idx];
            idx += s->f4;
        }
        for (i = 0; i < e->n12 / 2; i++) {
            s->p20[i] = e->p4[idx];
            s->p24[i] = e->p8[idx];
            idx += s->f4;
        }
    }
    e = &s->e[s->f3][j];
    q = n / s->f4;
    rem = s->f14 + q - s->f1C;
    if (rem < 0) {
        e->n10 = q * 2;
        e->n12 = 0;
        e->offC = s->f14;
        s->f14 += q;
    } else {
        e->n10 = (q - rem) * 2;
        e->n12 = rem * 2;
        e->offC = s->f14;
        s->f14 = rem;
    }
    e->f0 = q;
    e->f2 = n;
}

/* game_libs_func_0001CC98: publish the flagged 0x20-byte element of every record
 * (TU-local, baked jal callee; section 0x31304 not exported). Base = bootup.uso
 * Data sym1255 @0x345C0 (lui/addiu t0 held), spelled as a TYPED struct through the
 * per-site alias D_345c0_1CC98 (pinned 0 in undefined_syms_auto.txt; the file's
 * plain `extern int D_00000000_345c0` can't be retyped in this TU). For each of
 * count (+0x2070) records (stride 0xD0, element at +0xB0) in recs (+0x2CFC): if the
 * element's top flag bit is set, struct-copy it into elems (+0x14)[count*arg0 + i]
 * and clear its bit 30, else clear the destination's top bit; then zero byte +6.
 * BYTE-EXACT 51/51. The old NM (78.5) hand-wrote the off += 0xD0 cursor, the 8 word
 * copies and the byte masks; every char-arithmetic / int-cast / compound spelling of
 * &recs[i].e put the loaded base first (`addu a0,t6,a1`), only member access through
 * the typed global (`&G.recs[i].e`) gives the target's SR-cursor-first `addu a0,a1,t6`. */
typedef struct { unsigned flag:1, live:1, rest:30; char p4[2]; unsigned char b6; char p7; int w[6]; } gl_1CC98_Elem;
typedef struct {
    char p0[0x1C];
    int w1C;
    char p20[0x30 - 0x20];
    unsigned char b30;
    unsigned char b31;
    char p32[1];
    unsigned char b33;
    unsigned char b34;
    unsigned char b35;
    short h36;
    char p38[0x40 - 0x38];
    int w40;
    gl_1CC98_Elem *elem;
    int w48;
    char p4C[0x58 - 0x4C];
    float f58;
    char p5C[0x60 - 0x5C];
    unsigned char b60;
    char p61[0x82 - 0x61];
    short h82;
    short h84;
    char p86[0xA0 - 0x86];
    unsigned char bA0;
    char pA1[0xB0 - 0xA1];
    gl_1CC98_Elem e;
} gl_1CC98_Rec;
typedef struct { short active; short key; char p4[8]; } gl_260B4_Ent;
typedef struct { char p0[2]; unsigned char sel0; unsigned char sel1; char p4[0x10]; } gl_260B4_Reg;
typedef struct { char p0; unsigned char b1; unsigned char b2; unsigned char b3; char p4[0x158 - 4]; } gl_1CD64_Slot;
typedef struct {
    char p0[1];
    signed char nslots;
    char p2_[0x10 - 2];
    int w10;
    gl_1CC98_Elem *elems;
    gl_1CD64_Slot slots[23];
    char p1[0x2030 - 0x18 - 23 * 0x158];
    gl_260B4_Reg *regs;
    char p1b[0x2040 - 0x2034];
    short n2040;
    short h2042;
    short h2044;
    short h2046;
    char p1c[0x2070 - 0x2048];
    int count;
    char p2[0x2198 - 0x2074];
    char tbl2198[4];
    char p2c[0x2534 - 0x219C];
    int nents;
    char p2b[0x2540 - 0x2538];
    gl_260B4_Ent ents[(0x2CFC - 0x2540) / 0xC];
    gl_1CC98_Rec *recs;
    char p3[0x5378 - 0x2D00];
    char tbl5378[4];
} gl_1CC98_GS;
extern gl_1CC98_GS D_345c0_1CC98;
void game_libs_func_0001CC98(int arg0) {
    int i;
    gl_1CC98_Elem *s;
    gl_1CC98_Elem *d;
    for (i = 0; i < D_345c0_1CC98.count; i++) {
        s = &D_345c0_1CC98.recs[i].e;
        d = &D_345c0_1CC98.elems[D_345c0_1CC98.count * arg0 + i];
        if (s->flag) {
            *d = *s;
            s->live = 0;
        } else {
            d->flag = 0;
        }
        s->b6 = 0;
    }
}

/* gl_func_0001CD64: per-frame batch builder over bootup.uso sym1255 (shared typed alias
 * D_345c0_1CC98; all three lui/addiu pairs are sym1255 addend 0). Exported (section
 * 0x313D0 = sym1259, TextReloc ref @0x3ACA4). Points G.elems (+0x14) at a 4 KB stack
 * buffer; drains n = G.n2040 (+0x2040) calling blank sym1260(n-1) and the TU-local
 * 1CC98(G.n2040 - n) (baked jal gl_ref_00031304); then for each remaining batch portions
 * the budget (clamped by +0x2042/+0x2044/+0x2046), calls the baked jal gl_ref_00031050 for
 * every slot (G.slots +0x18, stride 0x158, count signed byte +1) whose b1 is set, and builds
 * the batch with gl_ref_00032320 (= 1DCB4) advancing the 8-byte display-list cursor; finally
 * a b2 countdown / b3 toggle sweep over the slots. *outLen = cursor - gfx (8-byte units).
 * BYTE-EXACT 129/129. The old NM (61.1) cached `char *g`, a `short` count (sll/sra
 * re-narrowing) and hand cursors. Levers: plain loops over the typed alias (fresh s0 slot
 * IVs, count/nslots re-reads), scalars declared BEFORE the 4 KB buf (decl-order frame map:
 * 7 homes above buf at sp+0x4C), a separate `cur = src` copy after the drain loop (s1 -> s7),
 * the clamp written `if (v >= lo) lo; else if (v <= hi) hi; else h2042` (branch-likely
 * layout), and `G.elems = buf;` before `p = gfx;` (or s8,a0 in the blez delay slot). */
typedef struct { int w0; int w1; } gl_1CD64_Gfx;
extern int gl_func_00000000();
extern void gl_ref_00031304();
extern void gl_ref_00031050();
extern gl_1CD64_Gfx *gl_ref_00032320();
gl_1CD64_Gfx *gl_func_0001CD64(gl_1CD64_Gfx *gfx, int *outLen, int *src, int budget) {
    gl_1CD64_Gfx *p;
    int *cur;
    int n;
    int i;
    int total;
    int portion;
    int v;
    gl_1CC98_Elem buf[128];

    D_345c0_1CC98.elems = buf;
    p = gfx;
    for (n = D_345c0_1CC98.n2040; n > 0; n--) {
        gl_func_00000000(n - 1);
        gl_ref_00031304(D_345c0_1CC98.n2040 - n);
    }
    cur = src;
    D_345c0_1CC98.w10 = 0;
    for (n = D_345c0_1CC98.n2040; n > 0; n--) {
        total = D_345c0_1CC98.n2040;
        if (n == 1) {
            portion = budget;
        } else {
            v = budget / n;
            if (v >= D_345c0_1CC98.h2044) {
                portion = D_345c0_1CC98.h2044;
            } else if (v <= D_345c0_1CC98.h2046) {
                portion = D_345c0_1CC98.h2046;
            } else {
                portion = D_345c0_1CC98.h2042;
            }
        }
        for (i = 0; i < D_345c0_1CC98.nslots; i++) {
            if (D_345c0_1CC98.slots[i].b1) {
                gl_ref_00031050(portion, total - n, i);
                total = D_345c0_1CC98.n2040;
            }
        }
        p = gl_ref_00032320(cur, portion, p, total - n);
        budget -= portion;
        cur += portion;
    }
    for (i = 0; i < D_345c0_1CC98.nslots; i++) {
        if (D_345c0_1CC98.slots[i].b2) {
            D_345c0_1CC98.slots[i].b2--;
        }
        D_345c0_1CC98.slots[i].b3 ^= 1;
    }
    *outLen = p - gfx;
    return p;
}

/* Clears bit 7 of the byte field of consecutive elements in the 2D global
 * table at &D_00000000 (D+0x14 = base ptr, D+0x2070 = row stride, D+0x2040 =
 * s16 element count), column a1, starting at row a0+1, until an element whose
 * bit 30 is set. BYTE-EXACT 29/29 2026-09-11 (agent-c): the old "14 $t-register
 * fields differ, loop $t-renumber, permuter-resistant" residual was two
 * spellings -- (1) the row address must be PRODUCT FIRST, `stride * v0 * 32 +
 * base + v1` (base-first, `(base | 0)`, `<< 5`, pointer-typed base and (int)
 * casts all number the base AFTER the product: `addu t1,t9,t0`); (2) the
 * `lw; sll t4,t2,1; bltz t4` bit-30 test with the skipped $t3 is a 1-bit
 * BITFIELD read (ugen numbers the extraction's srl temp, uopt folds it into
 * bltz); `(x << 1) < 0`, `x & 0x40000000`, `(x >> 30) & 1` keep consecutive
 * temps. Plain rotated `while (v0 < count)` (the bottom-test copy is uopt's,
 * renumbered `lh t8`); the do/while + guard form numbers both tests t6.
 * docs/IDO_CODEGEN.md#same-stride-cursor-sweep-iv-init-order-33b6c (tail).
 * Reloc-blind (&D_00000000). */
typedef struct { unsigned b0:1, b1:1, rest:30; } ElemFlags1CF68;
void game_libs_func_0001CF68(int a0, int a1) {
    int v0 = a0 + 1;
    int v1 = a1 << 5;

    while (v0 < *(short *)((char *)&D_00000000 + 0x2040)) {
        char *elem = (char *)((*(unsigned int *)((char *)&D_00000000 + 0x2070) * v0) * 32
            + *(int *)((char *)&D_00000000 + 0x14) + v1);
        if (((ElemFlags1CF68 *)elem)->b1) {
            break;
        }
        *(unsigned char *)elem = *(unsigned char *)elem & 0xFF7F;
        v0++;
    }
}


// gl_func_0001CFDC — STRUCTURAL PASS (0xD0 / 52 words, no episode).
// Raw-.word USO form (game_libs RSP/graphics-library segment).
// Hand-decoded.
//
// game_libs glyph / sprite draw helper (returns advance width).
//
//   int gl_func_0001CFDC(int code, Spec spec) {           // spec by value
//     int hi = spec.0x2;
//     E *e = &D_0 + idx(code) ;  e += 0x50;                // glyph entry
//     int w = e->0x10;  int h = e->0x0E;                   // metrics
//     v0 = jal 0x31FB0(0x3E0, …, w, h, hi);                // blit pass 1
//     if (e->0x12 != 0) {                                  // outline/shadow
//       v0 = jal 0x31FB0(0x3E0, e->0x10, 0, …, spec.0x2);  // blit pass 2
//       v0 &= 0xFFFF;
//     }
//     return v0;                                            // advance
//   }
//
// Struct-typing reference:
//   code = glyph/char code; &D_0 = global glyph-table base, entry
//     reached by index then +0x50; e->0x10 = width / advance,
//     e->0x0E = height, e->0x12 = secondary-pass flag (shadow /
//     outline), e->0x1B a u8 attribute. spec = a small by-value
//     struct (halfword fields at +0x2 / +0x32). 0x31FB0 = a fixed
//     intra-USO blit routine (real target, NOT a runtime placeholder);
//     0x3E0 = a blit mode/format constant. Text/sprite rendering.
// Caps (DEFERRED): single jr $ra. Real-C structural body below per
//   the analysis; byte-match deferred — the fixed-target call
//   (jal 0x31FB0) needs its real intra-USO symbol, and the
//   idx*0x158 / attr*0x64 / sub*0x14 index-multiply chains plus the
//   beql (e->0x12==0) skip are IDO-schedule-sensitive. Name
//   pre-checked: no extern reuse (occ all in this comment), so a
//   typed def is collision-safe. gl_func_00000000 = canonical
//   never-defined USO placeholder for the 0x31FB0 blit routine.
//   Next pass: resolve the 0x31FB0 symbol, then grind the
//   multiply-sequence + beql codegen.
/* EXACT 2026-10-17 agent-c run 106 (87.3 -> 100): the spec is an 8-byte
 * struct passed BY VALUE (lh 46/50(sp) read its halves from the a1/a2
 * homes), the glyph entry is addressed through a typed record view
 * (&rec->grp[rec->attr].ent[sub]; flat byte arithmetic commutes one addu),
 * and the blit is the baked in-unit jal 0x31FB0 (gl_ref_00031FB0 pin). */
extern int gl_ref_00031FB0(); /* baked in-unit jal 0x31FB0 (blit) */
typedef struct { short h0, h1, h2, h3; } Spec8_1CFDC;
typedef struct { char p[0xE]; unsigned short w; short h; short n; } Ent_1CFDC;
typedef struct { Ent_1CFDC ent[5]; } Grp_1CFDC;
typedef struct { char p[0x1B]; unsigned char attr; char p2[0x50 - 0x1C]; Grp_1CFDC grp[2]; char p3[0x40]; } Rec_1CFDC;
int gl_func_0001CFDC(int code, Spec8_1CFDC spec) {
    Ent_1CFDC *e;
    Rec_1CFDC *rec;
    int r;
    rec = &((Rec_1CFDC *)&D_00000000)[spec.h1];
    e = &rec->grp[rec->attr].ent[spec.h3];
    r = gl_ref_00031FB0(code, 0x3E0, e->w, e->h, spec.h1);
    if (e->n != 0) {
        r = gl_ref_00031FB0(r, (e->h + 0x3E0) & 0xFFFF, 0, e->n, spec.h1);
    }
    return r;
}

// gl_func_0001D0AC — STRUCTURAL PASS (0x154 / 85 words, no episode).
// Raw-.word USO form (game_libs). BOUNDARY NOTE: 2-jr USO bundle
// (named fn + 1 tiny trailing setter `sw t9,4(t8)`) — deferred USO
// re-split. Near-identical SIBLING of gl_func_0001CFDC (same glyph/
// sprite draw helper; differs only in the fixed blit target).
//
//   int gl_func_0001D0AC(int code, Spec spec) {           // spec by value
//     E *e = (&D_0 + idx(code)) + 0x50;                    // glyph entry
//     int w = e->0x10;  int h = e->0x0E;
//     v0 = jal 0x31F4C(0x3E0, …, w, h, spec.0x2);          // blit pass 1
//     if (e->0x12 != 0) {                                  // shadow pass
//       v0 = jal 0x31F4C(0x3E0, e->0x10, 0, …, spec.0x2);
//       v0 &= 0xFFFF;
//     }
//     return v0;                                            // advance
//   }
//
// Struct-typing reference: identical to gl_func_0001CFDC (see its
//   comment) — &D_0 glyph table, entry+0x50, e->0x10 width/advance,
//   e->0x0E height, e->0x12 secondary-pass flag, spec by-value
//   halfword struct, 0x3E0 blit mode. The ONLY difference: this
//   variant calls the fixed blit routine at 0x0C00C813 (≈0x31F4C)
//   instead of gl_func_0001CFDC's 0x0C00C7EC (≈0x31FB0) — likely a
//   different render target / layer.
// Caps (DEFERRED): single jr $ra (older "unsplit bundle" note is
//   STALE; .s is 0xD0/52 words, one function). Exact structural TWIN
//   of gl_func_0001CFDC — identical glyph-draw logic, only the blit
//   jal target differs (0xC813 -> 0x3204C here vs 0xC7EC -> 0x31FB0).
//   Real-C structural body below; byte-match deferred (resolve the
//   0x3204C blit symbol + the idx*0x158 / attr*0x64 / sub*0x14
//   index-multiply chains + beql codegen). Name pre-checked: no
//   extern reuse (collision-safe). gl_func_00000000 = canonical
//   never-defined USO placeholder for the 0x3204C blit routine.
/* EXACT 2026-10-17 agent-c run 106 (87.3 -> 100): gl_func_0001CFDC twin
 * (same typed view and by-value spec); blit = baked jal 0x3204C. */
extern int gl_ref_0003204C(); /* baked in-unit jal 0x3204C (blit) */
int gl_func_0001D0AC(int code, Spec8_1CFDC spec) {
    Ent_1CFDC *e;
    Rec_1CFDC *rec;
    int r;
    rec = &((Rec_1CFDC *)&D_00000000)[spec.h1];
    e = &rec->grp[rec->attr].ent[spec.h3];
    r = gl_ref_0003204C(code, 0x3E0, e->w, e->h, spec.h1);
    if (e->n != 0) {
        r = gl_ref_0003204C(r, (e->h + 0x3E0) & 0xFFFF, 0, e->n, spec.h1);
    }
    return r;
}

/* game_libs_func_0001D17C EXACT 2026-10-23 (agent-c run 140, 96.21 -> 100): OoT's
 * AudioSynth_LeakReverb in the older (SM64-era) index form: `(cmd, s32 reverbIndex)`
 * with every field read written as gSynthesisReverbs[reverbIndex].leakRtl / .leakLtr
 * (a named `reverb` pointer local colours the base v1 instead of a3). One DMEM move +
 * two aMix packets (DMEM_WET_TEMP 0x3E0 is the scratch). Retires the NCC NM donor. */
typedef struct { u32 w0; u32 w1; } gl_1D17C_Awords;
typedef union { gl_1D17C_Awords words; long long force_structure_alignment; } gl_1D17C_Acmd;
#define _SHIFTL(v, s, w) ((u32)(((u32)(v) & ((0x01 << (w)) - 1)) << (s)))
#define A_DMEMMOVE 10
#define DMEM_1CH_SIZE 0x1A0
#define aDMEMMove(pkt, i, o, c) { gl_1D17C_Acmd *_a = (gl_1D17C_Acmd *)pkt; _a->words.w0 = _SHIFTL(A_DMEMMOVE, 24, 8) | _SHIFTL(i, 0, 24); _a->words.w1 = _SHIFTL(o, 16, 16) | _SHIFTL(c, 0, 16); }
#define A_MIXER 12
#define DMEM_WET_TEMP 0x3E0
#define DMEM_WET_LEFT_CH 0xC80
#define DMEM_WET_RIGHT_CH 0xE20
#define aMix(pkt, f, g, i, o) { gl_1D17C_Acmd *_a = (gl_1D17C_Acmd *)pkt; _a->words.w0 = (_SHIFTL(A_MIXER, 24, 8) | _SHIFTL(f, 16, 8) | _SHIFTL(g, 0, 16)); _a->words.w1 = _SHIFTL(i, 16, 16) | _SHIFTL(o, 0, 16); }
typedef struct { char pad[0x28]; u16 leakRtl; u16 leakLtr; char pad2c[0x158 - 0x2C]; } gl_1D17C_Reverb;
#define gl_1D17C_gSynthesisReverbs ((gl_1D17C_Reverb *)&D_00000000)

gl_1D17C_Acmd *game_libs_func_0001D17C(gl_1D17C_Acmd *cmd, s32 reverbIndex) {
    aDMEMMove(cmd++, DMEM_WET_LEFT_CH, DMEM_WET_TEMP, DMEM_1CH_SIZE);
    aMix(cmd++, DMEM_1CH_SIZE >> 4, gl_1D17C_gSynthesisReverbs[reverbIndex].leakRtl, DMEM_WET_RIGHT_CH, DMEM_WET_LEFT_CH);
    aMix(cmd++, DMEM_1CH_SIZE >> 4, gl_1D17C_gSynthesisReverbs[reverbIndex].leakLtr, DMEM_WET_TEMP, DMEM_WET_RIGHT_CH);
    return cmd;
}
#undef _SHIFTL
#undef A_DMEMMOVE
#undef DMEM_1CH_SIZE
#undef aDMEMMove
#undef A_MIXER
#undef DMEM_WET_TEMP
#undef DMEM_WET_LEFT_CH
#undef DMEM_WET_RIGHT_CH
#undef aMix
#undef gl_1D17C_gSynthesisReverbs

// gl_func_0001D200 — STRUCTURAL PASS (0x2C0 / 176 words, no episode).
// Raw-.word USO form (game_libs). BOUNDARY NOTE: 2-jr USO bundle
// (named fn + 1 trailing helper) — deferred USO re-split. Same glyph-
// table FAMILY as gl_func_0001CFDC / gl_func_0001D0AC, but the larger
// STRING-draw variant: it loops over a packed glyph spec, accumulating
// an advance, rather than drawing a single glyph.
//
//   int gl_func_0001D200(args…, Spec spec) {            // spec by value
//     E *base = &D_0 + idx(...);                         // glyph table
//     E *e = base + 0x50;
//     int packed = e->0x5C;                              // word at +0x5C
//     short flags = e->0x60;                             // halfword +0x60
//     int lo = packed & 7;                               // 3-bit field
//     int hi = (packed >> 4) & 0xFFF;                     // 12-bit field
//     ... pack glyph metrics into sp+0x38/0x3A/0x3C ...
//     v0 = jal 0x31FB0(0x3E0, …, 0x1A0, w, h, spec.0x2); // blit row
//     if (cond) { ... second pass ... }
//     // tail: lui/addiu builds a &D_xxxx table pointer for caller
//     return v0;                                          // advance px
//   }
//
